<?php
declare(strict_types=1);
require_once __DIR__.'/harness.php';require_once __DIR__.'/database.php';require_once __DIR__.'/support-c-fixture.php';require_once __DIR__.'/support-d-fixture.php';
use Hostider\Core\Id;
use Hostider\Support\Mail\Attachments;
function eaSurface(string $surface,bool $uploads): void
{
    $g=cFixture();$t=bTicket($g);bReply($g,$t);bReply($g,$t,'note');$server=new HttpTestServer(dirname(__DIR__),bEnvironment($g),__DIR__.'/commerce-router.php');$client=['cookies'=>[],'csrf'=>''];$admin=$client;$other=$client;
    try{dClientLogin($server,$g['client'],$client);bLogin($server,$g['admin'],$admin);dClientLogin($server,$g['other'],$other);$route='/api/v1/client/'.$surface.'/detail?id='.$t['id'];$r=bHttp($server,$route,$client);same(200,$r[0]);$messages=$r[1]['data']['messages'];same(2,count($messages));$own=null;$staff=null;foreach($messages as $message){same(false,array_key_exists('author_id',$message));foreach(['session_id','identity_version','native_reference','system_origin'] as $key){same(false,array_key_exists($key,$message));}if($message['body']==='Synthetic request'){$own=$message;same(true,$message['can_attach']);}else{$staff=$message;same('Synthetic reply',$message['body']);same(false,$message['can_attach']);}}same(true,is_array($own));same(true,is_array($staff));same(false,str_contains($r[2],$g['admin']['user']));same(false,str_contains($r[2],'Synthetic note'));same(404,bHttp($server,$route,$other)[0]);$a=bHttp($server,'/api/v1/admin/'.$surface.'/detail?id='.$t['id'],$admin);same(200,$a[0]);same(3,count($a[1]['data']['messages']));foreach($a[1]['data']['messages'] as $message){same(true,array_key_exists('author_id',$message));if($message['body']==='Synthetic reply'){same($g['admin']['user'],$message['author_id']);same(true,$message['can_attach']);}if($message['type']==='internal_note'){same('Synthetic note',$message['body']);same(false,$message['can_attach']);}}
        if(!$uploads){return;}$version=(int)bRow($g,$t)['version'];$p=['ticket_id'=>$t['id'],'message_id'=>$own['id'],'version'=>$version,'name'=>'audit.pdf','base64'=>base64_encode(Attachments::FIXTURE)];$path='/api/v1/client/support-mail/upload';same(403,bHttp($server,$path,$client,$p,csrf:false)[0]);same(422,bHttp($server,$path,$client,$p+['can_attach'=>true])[0]);$bad=$p;$bad['message_id']=$staff['id'];same(404,bHttp($server,$path,$client,$bad)[0]);$foreign=bTicket($g,who:$g['other']);$bad=$p;$bad['ticket_id']=$foreign['id'];same(404,bHttp($server,$path,$client,$bad)[0]);same(404,bHttp($server,$path,$other,$p)[0]);$key=Id::uuid();$saved=bHttp($server,$path,$client,$p,$key);same(200,$saved[0]);same($version+1,$saved[1]['data']['version']);same($saved[1]['data'],bHttp($server,$path,$client,$p,$key)[1]['data']);same(1,(int)$g['db']->execute('SELECT COUNT(*) FROM support_mail_files WHERE message_id=?',[$own['id']])->fetchColumn());same(409,bHttp($server,$path,$client,$p)[0]);$g['db']->execute("UPDATE identity_sessions SET revoked_at=UTC_TIMESTAMP(6) WHERE user_id=? AND context='client'",[$g['client']['user']]);same(401,bHttp($server,$route,$client)[0]);same(401,bHttp($server,$path,$client,$p,$key)[0]);
    }finally{$server->stop();}
}
test('F5-E audit UI HTTP redacts message authors and preserves native own attachment CSRF stale replay revoke guards',fn()=>eaSurface('support-ui',true));
test('F5-E audit legacy HTTP redacts message authors while preserving public messages admin notes and tenant isolation',fn()=>eaSurface('support',false));
test('F5-E audit can_attach follows current reply grant and never substitutes for native upload authorization',function(): void{$g=cFixture();$t=bTicket($g);$reply=bReply($g,$t);$server=new HttpTestServer(dirname(__DIR__),bEnvironment($g),__DIR__.'/commerce-router.php');$a=['cookies'=>[],'csrf'=>''];try{bLogin($server,$g['admin'],$a);$g['db']->execute("DELETE g FROM identity_grants g JOIN identity_assignments a ON a.id=g.assignment_id WHERE a.user_id=? AND g.permission='support.ticket.reply'",[$g['admin']['user']]);$message=null;foreach(['support-ui','support'] as $surface){$r=bHttp($server,'/api/v1/admin/'.$surface.'/detail?id='.$t['id'],$a);same(200,$r[0]);foreach($r[1]['data']['messages'] as $m){if($m['body']==='Synthetic reply'){$message=$m;same($g['admin']['user'],$m['author_id']);same(false,$m['can_attach']);}}}same(true,is_array($message));$p=['ticket_id'=>$t['id'],'message_id'=>$message['id'],'version'=>$reply['version'],'name'=>'denied.pdf','base64'=>base64_encode(Attachments::FIXTURE)];same(404,bHttp($server,'/api/v1/admin/support-mail/upload',$a,$p)[0]);same(422,bHttp($server,'/api/v1/admin/support-mail/upload',$a,$p+['can_attach'=>true])[0]);same(0,(int)$g['db']->execute('SELECT COUNT(*) FROM support_mail_files')->fetchColumn());}finally{$server->stop();}});
if(realpath($_SERVER['SCRIPT_FILENAME']??'')===__FILE__){exit(executeTests());}
